        if (toEscalate.isEmpty()) {
            return;
        }

        fflib_IDomains.UnitOfWork uow = Application.UnitOfWork.newInstance();

        Date tomorrow = Date.today().addDays(1);

        for (Case c : toEscalate) {
            c.IsEscalated = true;
            c.Priority = 'High';
            uow.registerDirty(c);

            Task t = new Task(
                Subject = 'Escalated: ' + reason,
                WhatId = c.Id,
                OwnerId = c.OwnerId,
                ActivityDate = tomorrow,
                Priority = 'High'
            );
            uow.registerNew(t);
        }

        uow.commitWork();
    }
