        List<Contact> toUpdate = new List<Contact>();

        for (Contact c : contacts) {
            if (String.isNotBlank(c.Phone)) {
                c.Phone = stripNonDigitsPlus(c.Phone);
                toUpdate.add(c);
            }
        }

        if (!toUpdate.isEmpty()) {
            List<Database.SaveResult> results = Database.update(toUpdate, false);
            for (Database.SaveResult sr : results) {
                if (!sr.isSuccess()) {
                    Database.Error err = sr.getErrors().get(0);
                    errors.put(sr.getId(), err.getMessage());
                }
            }
        }

        return errors;
    }

    private static String stripNonDigitsPlus(String phone) {
        String cleaned = '';
        for (Integer i = 0; i < phone.length(); i++) {
            Character ch = phone.substring(i, i + 1);
            if (ch == '+' || (ch >= '0' && ch <= '9')) {
                cleaned += ch;
            }
        }
        return cleaned;
    }
}
