        if (!this._hasLoaded) {
            this._hasLoaded = true;
            this.loadOpportunities();
        }
    }

    loadOpportunities() {
        this.isLoading = true;
        this.error = null;

        getOpenOpportunities({ accountId: this.recordId })
            .then((result) => {
                this.opportunities = result;
                this.isLoading = false;
            })
            .catch((error) => {
                this.error = error;
                this.isLoading = false;
            });
    }

    handleRetry() {
        this.loadOpportunities();
    }

    get hasError() {
        return this.error !== null;
    }

    get hasOpportunities() {
        return this.opportunities !== null && this.opportunities.length > 0;
    }

    get isEmpty() {
        return this.opportunities !== null && this.opportunities.length === 0;
    }

    get errorMessage() {
        if (this.error && this.error.body && this.error.body.message) {
            return this.error.body.message;
        }
        return this.error ? this.error.message : '';
    }
}
