public class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // --- Validate map is not null or empty ---
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('percentByGauId must not be null or empty.');
        }

        // --- Validate each percentage value ---
        Decimal totalPercent = 0;
        List<Id> gauIds = new List<Id>();
        for (Map.Entry<Id, Decimal> entry : percentByGauId.entrySet()) {
            if (entry.getValue() == null || entry.getValue() <= 0) {
                throw new AllocationException(
                    'Each percentage must be a non-null value greater than 0. '
                    + 'Offending GAU: ' + entry.getKey());
            }
            totalPercent += entry.getValue();
            gauIds.add(entry.getKey());
        }

        // --- Validate total does not exceed 100% ---
        if (totalPercent > 100) {
            throw new AllocationException(
                'Percentages add up to more than 100%. Total: ' + totalPercent + '%');
        }

        // --- Validate all referenced GAUs exist and are active ---
        Map<Id, npsp__General_Accounting_Unit__c> gauMap =
            new Map<Id, npsp__General_Accounting_Unit__c>(
                [SELECT Id, npsp__Is_Active__c
                 FROM npsp__General_Accounting_Unit__c
                 WHERE Id IN :gauIds]
            );

        for (Id gauId : gauIds) {
            npsp__General_Accounting_Unit__c gau = gauMap.get(gauId);
            if (gau == null || !gau.npsp__Is_Active__c) {
                throw new AllocationException(
                    'GAU is inactive or does not exist: ' + gauId);
            }
        }

        // --- All validations passed; now mutate data ---

        // Delete all existing GAU allocations for this opportunity
        List<npsp__Allocation__c> existingAllocs = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existingAllocs.isEmpty()) {
            Delete existingAllocs;
        }

        // Build and insert new allocations using percentage.
        // NPSP's platform triggers will compute npsp__Amount__c from
        // npsp__Percentage__c × Opportunity.Amount, and will recalculate
        // automatically whenever the opportunity amount changes.
        List<npsp__Allocation__c> newAllocs = new List<npsp__Allocation__c>();
        for (Map.Entry<Id, Decimal> entry : percentByGauId.entrySet()) {
            newAllocs.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = entry.getKey(),
                npsp__Percentage__c = entry.getValue()
            ));
        }

        Insert newAllocs;

        return newAllocs;
    }
}
