public class GiftImportService {

    public class WebGift {
        public String firstName;
        public String lastName;
        public String email;
        public Decimal amount;
        public Date giftDate;
    }

    public class ImportResult {
        public Boolean success;
        public Id contactId;
        public Id opportunityId;
        public String errorMessage;
    }

    public static List<ImportResult> importGifts(List<WebGift> gifts) {
        List<ImportResult> results = new List<ImportResult>();

        if (gifts == null || gifts.isEmpty()) {
            return results;
        }

        // 1. Stage one DataImport__c record per gift
        List<DataImport__c> dataImports = new List<DataImport__c>(gifts.size());

        for (WebGift gift : gifts) {
            dataImports.add(new DataImport__c(
                Data_Type__c = 'Individual',
                First_Name__c = gift.firstName,
                Last_Name__c = gift.lastName,
                Email__c = gift.email,
                Amount__c = gift.amount,
                Closedate__c = gift.giftDate,
                Matching_Information__c = gift.email,
                Matching_Information2__c = gift.firstName,
                Matching_Information3__c = gift.lastName,
                Status__c = 'New'
            ));
        }

        insert dataImports;

        // 2. Collect staged IDs in input order
        List<Id> dataImportIds = new List<Id>(dataImports.size());
        for (DataImport__c di : dataImports) {
            dataImportIds.add(di.Id);
        }

        // 3. Process synchronously via NPSP's Data Import Apex API
        npsp__npsp_ProcessService.processDataImports(dataImportIds);

        // 4. Query back processed records to build results
        Map<Id, DataImport__c> processedMap = new Map<Id, DataImport__c>(
            [SELECT Id, Success__c, Error__c, Contact__c, Opportunity__c
             FROM DataImport__c
             WHERE Id IN :dataImportIds]
        );

        // 5. Build one ImportResult per gift, preserving input order
        for (Id id : dataImportIds) {
            ImportResult res = new ImportResult();
            DataImport__c di = processedMap.get(id);

            if (di != null) {
                res.success = di.Success__c;
                res.contactId = di.Contact__c;
                res.opportunityId = di.Opportunity__c;
                res.errorMessage = di.Success__c ? null : di.Error__c;
            } else {
                res.success = false;
                res.errorMessage = 'Data import record not found after processing.';
            }

            results.add(res);
        }

        return results;
    }
}
```

**Design notes:**

| Concern | How it's handled |
|---|---|
| **One DataImport per gift** | Each `WebGift` maps to exactly one `DataImport__c` with `Data_Type__c = 'Individual'`, which triggers NPSP's full flow: contact match → household → donation. |
| **Matching on FN/LN/Email** | Populated into `Matching_Information__c` (email), `Matching_Information2__c` (first), `Matching_Information3__c` (last), matching the org's default Data Import settings. |
| **Never match donations** | NPSP's default for the `Individual` data type always creates a new Opportunity; no donation matching fields are set. |
| **Synchronous, same transaction** | A single `insert` (≤ 200 rows) → one `processDataImports` call → one `SELECT`. The NPSP service processes all rows in the current transaction. |
| **Failed rows don't stop others** | NPSP's processing engine marks individual rows as rejected (`Success__c = FALSE`, `Error__c` populated) without rolling back the batch. We read back status per row. |
| **Bulk-safe for 200** | 1 DML + 1 SOQL in our code; NPSP's service is designed for up to 200 per invocation. No per-record loops for DML/SOQL. |
| **Audit trail** | DataImport__c records are left in the org (not deleted) after processing. |
| **Null/empty input** | Early-return with an empty list. |

