    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        TAF_Tx.disable(Account.sObjectType);
        try {
            List<Account> accounts = [SELECT Id, OwnerId FROM Account WHERE Id IN :accountIds];
            List<Contact> contacts = [SELECT Id, OwnerId FROM Contact WHERE AccountId IN :accountIds];

